as_number(node: Node) -> Option[float]:
    match node:
        case Node.integer(value, _):
            return Some(float(value))
        case Node.decimal(value, _, _):
            return Some(value)
        case Node.measure(value, _):
            return Some(value)
        case _:
            return None

lex_failure(src: bytes, problem: tk.LexError, options: ParseOptions) -> ParseError:
    span = span_at(src, problem.offset, options)
    message = problem.message
    if len(message) == 0:
        message = "unexpected character"
    return ParseError(message=message, line=span.line, col=span.col, offset=problem.offset)

parse_int(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    match int(token.text):
        case Some(value):
            return Ok(Step(node=ast.Node.integer(value, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

parse_float(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    match float(token.text):
        case Some(value):
            return Ok(Step(node=ast.Node.decimal(value, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

source_dimension_factor(src: bytes, token: tk.Token, options: ParseOptions) -> float:
    after = token.span.offset + len(token.text)
    for rule in options.dialect.numbers.dimensions:
        if tk.matches_text(src, after, rule.suffix):
            return rule.to_mm
    return 1.0

is_si_number_char(options: ParseOptions, byte: int, index: int) -> bool:
    predicate = options.dialect.chars.is_digit
    if predicate(byte):
        return True
    if byte == tk.char_byte(options.dialect.syntax.decimal_point):
        return True
    if byte == tk.char_byte(options.dialect.syntax.minus) and index == 0:
        return True
    return False

parse_si(token: tk.Token, next_pos: int, options: ParseOptions) -> Result[Step, ParseError]:
    text = token.text
    end = si_number_end(text, options)
    # A missing prefix or a suffixless text cannot be scaled; the tokenizer's
    # suffix rules make this unreachable for a real si_val token.
    if end == 0 or end == len(text):
        return Err(invalid_number(token))
    match float(text[0:end]):
        case Some(value):
            scaled = value * tk.scale_factor(options.dialect.numbers, text[end])
            # Keep the source spelling alongside the decoded value, exactly as
            # Zig's `Node.suffixedFloat` does: `100nF` and `100n` are the same
            # number, but only the first says which physical quantity it is.
            return Ok(Step(node=ast.Node.decimal(scaled, token.span, Some(text)), next=next_pos))
        case None:
            return Err(invalid_number(token))

parse_node(cursor: Cursor, depth: int) -> Result[Step, ParseError]:
    token = cursor.tokens[cursor.pos]
    next_pos = cursor.pos + 1
    match token.kind:
        case tk.Kind.lparen:
            return parse_list(cursor, next_pos, depth, token)
        case tk.Kind.rparen:
            return Err(located(token.span, unexpected_close(cursor.options, token)))
        case tk.Kind.atom:
            return Ok(Step(node=ast.Node.atom(token.text, token.span), next=next_pos))
        case tk.Kind.string:
            return Ok(Step(node=ast.Node.string(token.text, token.span), next=next_pos))
        case tk.Kind.int_val:
            return parse_int(token, next_pos)
        case tk.Kind.float_val:
            return parse_float(token, next_pos)
        case tk.Kind.unit_val:
            return parse_unit(cursor.src, token, next_pos, cursor.options)
        case tk.Kind.si_val:
            return parse_si(token, next_pos, cursor.options)
        case tk.Kind.eof:
            return Err(located(token.span, unclosed_list(cursor.options)))

parse_list(cursor: Cursor, pos: int, depth: int, open_token: tk.Token) -> Result[Step, ParseError]:
    if depth >= cursor.options.max_depth:
        return Err(located(open_token.span, "s-expression nesting is too deep"))
    entries: list[ast.Node] = []
    cursor_pos = pos
    while True:
        token = cursor.tokens[cursor_pos]
        # Point an unterminated list at the `(` that was never closed — the
        # actionable location, not the end of the file where scanning stopped.
        if token.kind == tk.Kind.eof:
            return Err(located(open_token.span, unclosed_list(cursor.options)))
        if token.kind == tk.Kind.rparen:
            cursor_pos = cursor_pos + 1
            break
        child = parse_node(Cursor(src=cursor.src, tokens=cursor.tokens, pos=cursor_pos, options=cursor.options), depth + 1)?
        entries.append(child.node)
        cursor_pos = child.next
    return Ok(Step(node=ast.Node.form(entries, open_token.span), next=cursor_pos))

matches_bytes(src: bytes, offset: int, pattern: bytes) -> bool:
    size = len(pattern)
    if size == 0:
        return False
    if offset < 0 or offset + size > len(src):
        return False
    index = 0
    while index < size:
        if src[offset + index] != pattern[index]:
            return False
        index = index + 1
    return True

find_scale(numbers: NumberPolicy, letter: str) -> Option[ScaleRule]:
    for rule in numbers.scales:
        if rule.letter == letter:
            return Some(rule)
    return None

has_unit_letter(numbers: NumberPolicy, letter: str) -> bool:
    for accepted in numbers.unit_letters:
        if accepted == letter:
            return True
    return False

char_at(lx: Lexer, offset: int) -> str:
    index = lx.pos + offset
    if index < 0 or index >= len(lx.src):
        return ""
    return lexeme(lx.src, index, index + 1)

advance(lx: Lexer):
    if lx.pos < len(lx.src):
        if lx.src[lx.pos] == lx.scan.newline:
            lx.line = lx.line + 1
            lx.col = 1
        else:
            lx.col = lx.col + 1
        lx.pos = lx.pos + 1

space_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_space
    return predicate(byte)

digit_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_digit
    return predicate(byte)

atom_start_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_atom_start
    return predicate(byte)

atom_continue_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_atom_continue
    return predicate(byte)

operator_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_operator
    return predicate(byte)

operator_tail_byte(lx: Lexer, byte: int) -> bool:
    predicate = lx.chars.is_operator_tail
    return predicate(byte)

read_string(lx: Lexer, line: int, col: int, offset: int) -> Result[Token, LexError]:
    advance(lx)  # skip opening quote
    start = lx.pos
    closed = False
    while lx.pos < len(lx.src) and not closed:
        ch = lx.src[lx.pos]
        if ch == lx.scan.escape:
            advance(lx)  # skip escape byte
            advance(lx)  # skip escaped char
        elif ch == lx.scan.quote:
            closed = True
        else:
            advance(lx)
    if not closed:
        return Err(LexError(message="unterminated string", offset=offset, line=line))
    text = lexeme(lx.src, start, lx.pos)
    advance(lx)  # skip closing quote
    return Ok(Token(kind=Kind.string, text=text, span=ast.Span(line=line, col=col, offset=offset)))

read_operator(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    advance(lx)
    if operator_tail_byte(lx, peek(lx)):
        advance(lx)
    return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))

read_number(lx: Lexer, numbers: NumberPolicy, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    if peek(lx) == lx.scan.minus:
        advance(lx)
    while digit_byte(lx, peek(lx)):
        advance(lx)
    is_float = False
    if peek(lx) == lx.scan.point and digit_byte(lx, peek_at(lx, 1)):
        is_float = True
        advance(lx)  # skip .
        while digit_byte(lx, peek(lx)):
            advance(lx)
    num_end = lx.pos
    # Dimension suffixes: the token text stops before the suffix.
    size = dimension_suffix_len(lx, numbers)
    if size > 0:
        step = 0
        while step < size:
            advance(lx)
            step = step + 1
        return Token(kind=Kind.unit_val, text=lexeme(lx.src, start, num_end), span=ast.Span(line=line, col=col, offset=offset))
    # SI scale (or a bare unit letter); the text keeps the suffix verbatim so
    # the parser can apply the scale.
    suffix = si_suffix_len(lx, numbers)
    if suffix > 0:
        step = 0
        while step < suffix:
            advance(lx)
            step = step + 1
        return Token(kind=Kind.si_val, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    # Percent literal: only when the sign ends the token, so a standalone `%`
    # still lexes as an operator atom.
    if peek(lx) == lx.scan.percent and not atom_continue_byte(lx, peek_at(lx, 1)):
        advance(lx)
        return Token(kind=Kind.si_val, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    if atom_continue_byte(lx, peek(lx)):
        while atom_continue_byte(lx, peek(lx)):
            advance(lx)
        return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    text = lexeme(lx.src, start, lx.pos)
    if is_float:
        return Token(kind=Kind.float_val, text=text, span=ast.Span(line=line, col=col, offset=offset))
    return Token(kind=Kind.int_val, text=text, span=ast.Span(line=line, col=col, offset=offset))

skip_trivia(lx: Lexer) -> Option[LexError]:
    skipping = True
    while skipping:
        byte = peek(lx)
        if space_byte(lx, byte):
            advance(lx)
        elif matches_bytes(lx.src, lx.pos, lx.scan.block_open):
            open_line = lx.line
            open_offset = lx.pos
            step = 0
            size = len(lx.scan.block_open)
            while step < size:
                advance(lx)
                step = step + 1
            closed = False
            while lx.pos < len(lx.src) and not closed:
                if matches_bytes(lx.src, lx.pos, lx.scan.block_close):
                    step = 0
                    size = len(lx.scan.block_close)
                    while step < size:
                        advance(lx)
                        step = step + 1
                    closed = True
                else:
                    advance(lx)
            if not closed:
                return Some(LexError(message="unterminated block comment", offset=open_offset, line=open_line))
        elif matches_bytes(lx.src, lx.pos, lx.scan.line_comment):
            while peek(lx) != -1 and peek(lx) != lx.scan.newline:
                advance(lx)
        else:
            skipping = False
    return None

tokenize_with(src: bytes, config: LexConfig) -> Result[list[Token], LexError]:
    lx = Lexer(src=src, pos=0, line=1, col=1, chars=config.chars, scan=scan_of(config.syntax))
    numbers = config.numbers
    tokens: list[Token] = []
    while True:
        match skip_trivia(lx):
            case Some(problem):
                return Err(problem)
            case None:
                pass
        line = lx.line
        col = lx.col
        offset = lx.pos
        byte = peek(lx)
        if byte == -1:
            tokens.append(Token(kind=Kind.eof, text="", span=ast.Span(line=line, col=col, offset=offset)))
            return Ok(tokens)
        if byte == lx.scan.open:
            advance(lx)
            tokens.append(Token(kind=Kind.lparen, text=lexeme(lx.src, offset, lx.pos), span=ast.Span(line=line, col=col, offset=offset)))
        elif byte == lx.scan.close:
            advance(lx)
            tokens.append(Token(kind=Kind.rparen, text=lexeme(lx.src, offset, lx.pos), span=ast.Span(line=line, col=col, offset=offset)))
        elif byte == lx.scan.quote:
            match read_string(lx, line, col, offset):
                case Ok(token):
                    tokens.append(token)
                case Err(problem):
                    return Err(problem)
        elif digit_byte(lx, byte) or (byte == lx.scan.minus and digit_byte(lx, peek_at(lx, 1))):
            tokens.append(read_number(lx, numbers, line, col, offset))
        elif atom_start_byte(lx, byte):
            tokens.append(read_atom(lx, line, col, offset))
        elif operator_byte(lx, byte):
            tokens.append(read_operator(lx, line, col, offset))
        else:
            return Err(LexError(message="unexpected character", offset=offset, line=line))

measured_width(text: str, fallback: int) -> int:
    if len(text) == 0:
        return fallback
    return len(text)

decimal_width(value: float) -> int:
    text = str(value)
    if text.endswith(".0"):
        return measured_width(text[0:len(text) - 2], fallback_float_width)
    return measured_width(text, fallback_float_width)

measure_width(value: float, layout: Layout) -> int:
    text = str(value)
    if text.endswith(".0"):
        return measured_width(text[0:len(text) - 2], fallback_unit_val_width) + len(layout.measure_suffix)
    return measured_width(text, fallback_unit_val_width) + len(layout.measure_suffix)

estimate_width(node: ast.Node, depth: int, layout: Layout) -> Option[int]:
    if depth > layout.depth_cutoff:
        return None
    match node:
        case ast.Node.form(entries, _):
            total = 2
            gap = len(layout.inline_separator)
            index = 0
            while index < len(entries):
                if index > 0:
                    total = total + gap
                match estimate_width(entries[index], depth + 1, layout):
                    case Some(width):
                        total = total + width
                    case None:
                        return None
                index = index + 1
            return Some(total)
        case ast.Node.atom(text, _):
            return Some(len(text))
        case ast.Node.string(content, _):
            return Some(len(content) + len(layout.string_quote) * 2)
        case ast.Node.integer(value, _):
            return Some(int_width(value))
        case ast.Node.decimal(value, _, literal):
            match literal:
                case Some(text):
                    return Some(literal_width(text))
                case None:
                    return Some(decimal_width(value))
        case ast.Node.measure(value, _):
            return Some(measure_width(value, layout))

indent_text_of(style: Style, columns: int) -> str:
    spell_indent = style.indent_text
    return spell_indent(columns)

render_with(nodes: list[ast.Node], style: Style) -> str:
    parts: list[str] = []
    index = 0
    while index < len(nodes):
        if index > 0:
            parts.append(style.layout.line_ending)
            parts.append(style.layout.top_level_gap)
        push_node(parts, nodes[index], 0, style)
        index = index + 1
    if style.layout.trailing_newline and len(nodes) > 0:
        parts.append(style.layout.line_ending)
    return "".join(parts)
